CREATE TABLE "people" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid,
	"full_name" text NOT NULL,
	"nickname" text,
	"family_branch" text,
	"birth_year" integer,
	"death_year" integer,
	"deceased" boolean DEFAULT false NOT NULL,
	"created_by_user_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "people_birth_year_check" CHECK ("birth_year" is null or "birth_year" between 1800 and 2200),
	CONSTRAINT "people_death_year_check" CHECK ("death_year" is null or "death_year" between 1800 and 2200),
	CONSTRAINT "people_years_order_check" CHECK ("birth_year" is null or "death_year" is null or "death_year" >= "birth_year"),
	CONSTRAINT "people_death_implies_deceased_check" CHECK ("death_year" is null or "deceased")
);--> statement-breakpoint
