ALTER TABLE "cuencada_itinerary_items" ALTER COLUMN "start_time" SET DATA TYPE time USING (
  CASE
    WHEN btrim("start_time") ~ '^([01]?[0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$' THEN btrim("start_time")::time
    WHEN btrim("start_time") ~* '^(0?[1-9]|1[0-2]):[0-5][0-9] ?[ap]\.? ?m\.?$'
      THEN to_timestamp(upper(replace(replace(btrim("start_time"), '.', ''), ' ', '')), 'HH12:MIAM')::time
    ELSE NULL
  END
);--> statement-breakpoint
